// Hand-written (NOT autogenerated). Guards inline struct fields, which
// tools/ulsdkbuild writes with generated.Create<Struct>.

package value

import (
	"reflect"
	"testing"
)

func TestVtri2DStructRoundTrip(t *testing.T) {
	want := &Vtri2D{V: Tri2D{
		P0: &Point2D{X: 1, Y: 2},
		P1: &Point2D{X: 3, Y: 4},
		P2: &Point2D{X: 5, Y: 6},
	}}
	got, err := Vtri2DFromBytes(want.ToBytes())
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("tri:\n got %#v\nwant %#v", got.V, want.V)
	}
}

// A struct is always present on the wire, so a nil nested struct is written
// as zero values.
func TestVtri2DNilNestedStruct(t *testing.T) {
	got, err := Vtri2DFromBytes((&Vtri2D{V: Tri2D{P1: &Point2D{X: 3, Y: 4}}}).ToBytes())
	if err != nil {
		t.Fatal(err)
	}
	if *got.V.P0 != (Point2D{}) || *got.V.P1 != (Point2D{X: 3, Y: 4}) || *got.V.P2 != (Point2D{}) {
		t.Fatalf("tri = %+v %+v %+v, want zero, {3 4}, zero", *got.V.P0, *got.V.P1, *got.V.P2)
	}
}
